mapper.select:
SELECT id, user_id, token, expires_at, revoked_at, created_at
FROM refresh_token
WHERE token = #{token}

mapper.update:
UPDATE refresh_token
SET revoked_at = #{revokedAt}
WHERE token = #{token}
  AND revoked_at IS NULL

UPDATE refresh_token
SET revoked_at = #{revokedAt}
WHERE user_id = #{userId}
  AND revoked_at IS NULL
